INSERT INTO public."art_gallery" ("id", "title", "short_description", "description", "image", "width", "height", "price", "type", "category", "availability", "quantity", "year", "dimensions", "options", "specs", "display_order", "created_at", "updated_at") VALUES ('art-012', 'Echoes of Antiquity', 'Classical gallery artwork frame inspired by ancient temple motifs.', 'Echoes of Antiquity bridges heritage craftsmanship with contemporary fine art photography. Featuring rich muted undertones and intricate traditional details.', 'https://res.cloudinary.com/ihvram9y/image/upload/v1790496547/art_gallery/klgmxdymro4aatuhqkcr.jpg', 1200, 1600, 640, 'Physical', 'Physical Prints', 'Collector Edition (1/5)', 5, '2025', '32 x 48 inches', '[{"id":"opt-echo-md","label":"24 x 36 in - Fine Art Matte","price":490},{"id":"opt-echo-lg","label":"32 x 48 in - Museum Archival Print","price":640},{"id":"opt-echo-xl","label":"40 x 60 in - Hand-framed Master Piece","price":1350}]'::jsonb, '{"paper":"Hahnemühle Museum Etching 350gsm","framing":"Unframed","printing":"Pigment Archival Print","signature":"Hand-signed certificate of authenticity"}'::jsonb, 13, '2026-09-09T05:47:44.751003+00:00', '2026-09-09T05:47:44.751003+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."art_gallery" ("id", "title", "short_description", "description", "image", "width", "height", "price", "type", "category", "availability", "quantity", "year", "dimensions", "options", "specs", "display_order", "created_at", "updated_at") VALUES ('art-010', 'Prism & Marble', 'High-resolution digital abstract study exploring refraction and fluid geometric symmetry.', 'An architectural exploration of light refraction on polished marble surfaces. A clean digital master print for modern office and gallery spaces.', 'https://res.cloudinary.com/ihvram9y/image/upload/v1790496547/art_gallery/hrccd2q3a4acuk9tnp3x.jpg', 1600, 1200, 260, 'Digital', 'Digital Prints', 'Instant Download', 999, '2024', '8000 x 6000 px (48 MP Digital Master)', '[{"id":"opt-prism-pers","label":"Personal Display File (High-Res JPG)","price":260},{"id":"opt-prism-comm","label":"Architectural License (16-Bit RAW TIFF)","price":540}]'::jsonb, '{"format":"16-Bit Uncompressed TIFF & 8K JPEG","license":"Commercial / Personal Display License","delivery":"Instant Digital File Access Link","colorSpace":"Adobe RGB (1998)"}'::jsonb, 11, '2026-09-09T05:47:44.751003+00:00', '2026-09-09T05:47:44.751003+00:00') ON CONFLICT DO NOTHING;
